package com.example.domain.model.i18n

internal object DuaFr1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("Au réveil", "Louange à Allah qui nous a redonné la vie après nous avoir fait mourir (le sommeil), et c'est vers Lui que se fera la résurrection.", "À dire dès le réveil, en signe de gratitude envers Allah.", "Le Prophète ﷺ la récitait au réveil — commencer la journée par la gratitude et le rappel de l'au-delà."),
        "dua_leaving_home" to DuaText("En sortant de la maison", "Au nom d'Allah, je place ma confiance en Allah, il n'y a de force ni de puissance qu'en Allah.", "À dire en quittant la maison, pour être protégé.", "Il est dit alors : tu es guidé, épargné et protégé, et le diable s'éloigne."),
        "dua_anxiety_distress" to DuaText("Invocation contre le souci et la tristesse", "Ô Allah, je cherche refuge auprès de Toi contre le souci et la tristesse, l'incapacité et la paresse, l'avarice et la lâcheté, le poids des dettes et la domination des hommes.", "En cas de souci, tristesse, dettes ou détresse mentale.", "Le Prophète ﷺ répétait souvent cette invocation contre le souci, la paresse et les dettes."),
        "dua_sayyidul_istighfar" to DuaText("Le maître des invocations de pardon", "Ô Allah, Tu es mon Seigneur, il n'y a de divinité que Toi. Tu m'as créé et je suis Ton serviteur, je m'en tiens à Ton pacte et Ta promesse autant que je le peux. Je cherche refuge auprès de Toi contre le mal que j'ai commis. Je reconnais Tes bienfaits envers moi et je reconnais mon péché, pardonne-moi donc, car nul ne pardonne les péchés hormis Toi.", "Matin et soir — la meilleure invocation de repentir enseignée par le Prophète ﷺ.", "Quiconque la dit le soir avec conviction et meurt cette nuit-là entre au Paradis ; de même le matin."),
        "dua_parents" to DuaText("Invocation pour les parents", "Seigneur, fais-leur miséricorde comme ils m'ont élevé tout petit.", "Invocation coranique pour les parents, en retour de leur éducation.", "Allah a Lui-même ordonné cette invocation pour les parents dans le Coran."),
        "dua_entering_mosque" to DuaText("En entrant à la mosquée", "Ô Allah, ouvre-moi les portes de Ta miséricorde.", "En entrant à la mosquée du pied droit.", "Le Prophète ﷺ a enseigné cette invocation en entrant à la mosquée."),
        "dua_morning_asbahna" to DuaText("Rappel du matin", "Nous voici au matin, et la royauté appartient à Allah au matin. Louange à Allah. Nulle divinité sauf Allah, Seul, sans associé. À Lui la royauté, à Lui la louange, et Il est capable de toute chose.", "Invocation prophétique à dire le matin.", "Commencer la journée en reconnaissant la royauté et l'unicité d'Allah."),
        "dua_evening_amsayna" to DuaText("Rappel du soir", "Nous voici au soir, et la royauté appartient à Allah au soir. Louange à Allah. Nulle divinité sauf Allah, Seul, sans associé. À Lui la royauté, à Lui la louange, et Il est capable de toute chose.", "Invocation prophétique à dire le soir.", "Commencer la nuit en reconnaissant la royauté et l'unicité d'Allah."),
        "dua_bismillah_la_yadurru" to DuaText("Protection contre tout mal", "Au nom d'Allah, avec le nom duquel rien sur terre ni au ciel ne peut nuire, et Il est Celui qui entend et qui sait tout.", "À dire trois fois le matin et trois fois le soir.", "Quiconque la dit trois fois matin et soir, rien ne pourra lui nuire."),
        "dua_raditu_billahi" to DuaText("Satisfait qu'Allah soit mon Seigneur", "Je suis satisfait qu'Allah soit mon Seigneur, l'Islam ma religion, et Muhammad ﷺ mon Prophète.", "À dire trois fois le matin et le soir.", "Allah S'engage à le satisfaire au Jour de la Résurrection."),
        "dua_hasbiyallah" to DuaText("Hasbiyallah (Allah me suffit)", "Allah me suffit, nulle divinité sauf Lui, je place ma confiance en Lui, et Il est le Seigneur du Trône immense.", "À dire sept fois le matin et le soir.", "Verset coranique ; Allah suffit face aux soucis du bas monde et de l'au-delà."),
        "dua_subhanallah_wa_bihamdihi" to DuaText("Gloire et louange à Allah", "Gloire à Allah et louange à Lui.", "À dire cent fois par jour.", "Quiconque le dit cent fois par jour, ses péchés sont effacés, fussent-ils aussi nombreux que l'écume de la mer."),
        "dua_tahleel_100" to DuaText("Nulle divinité sauf Allah, Seul", "Nulle divinité sauf Allah, Seul, sans associé. À Lui la royauté, à Lui la louange, et Il est capable de toute chose.", "Grand mérite à la dire cent fois par jour.", "Équivalent à affranchir dix esclaves, cent bonnes actions inscrites, cent péchés effacés, et protection du diable jusqu'au soir."),
        "dua_leaving_mosque" to DuaText("En sortant de la mosquée", "Ô Allah, je Te demande de Ta faveur.", "En sortant de la mosquée du pied gauche.", "Demander la faveur et la subsistance d'Allah en quittant la mosquée."),
        "dua_after_adhan" to DuaText("Après l'appel à la prière", "Ô Allah, Seigneur de cet appel parfait et de la prière qui va être accomplie, accorde à Muhammad al-Wasîla et la vertu, et élève-le au rang glorieux que Tu lui as promis.", "Juste après la fin de l'adhan.", "Quiconque la dit obtient l'intercession du Prophète ﷺ au Jour du Jugement."),
        "dua_after_salah_istighfar" to DuaText("Après la prière obligatoire", "Je demande pardon à Allah (trois fois). Ô Allah, Tu es la Paix et de Toi vient la paix, béni sois-Tu, ô Détenteur de la Majesté et de la Générosité.", "Juste après le salam de la prière.", "Le Prophète ﷺ la disait après chaque prière obligatoire."),
        "dua_after_salah_help_dhikr" to DuaText("Aide-moi à T'évoquer", "Ô Allah, aide-moi à T'évoquer, à Te remercier et à T'adorer excellemment.", "Après chaque prière — recommandation du Prophète ﷺ à Mu'adh.", "Recommandation prophétique spéciale pour l'excellence et la persévérance dans l'adoration."),
        "dua_ayatul_kursi" to DuaText("Le Verset du Trône après la prière", "Allah ! Nulle divinité que Lui, le Vivant, Celui qui subsiste par Lui-même. Ni somnolence ni sommeil ne Le saisissent. À Lui appartient tout ce qui est dans les cieux et sur la terre. Qui peut intercéder auprès de Lui sans Sa permission ? Il connaît leur passé et leur futur. Et de Sa science, ils n'embrassent que ce qu'Il veut. Son Trône déborde les cieux et la terre, dont la garde ne Lui coûte aucune peine. Et Il est le Très-Haut, le Très-Grand.", "Après chaque prière obligatoire et avant de dormir.", "Quiconque le récite après chaque prière obligatoire, seule la mort l'empêche d'entrer au Paradis ; avant de dormir, il est protégé jusqu'au matin."),
        "dua_before_sleep" to DuaText("Avant de dormir", "C'est en Ton nom, ô Allah, que je meurs (dors) et que je vis (me réveille).", "À dire après s'être allongé.", "Le Prophète ﷺ la disait avant de dormir."),
        "dua_sleep_tasbeeh" to DuaText("Le tasbîh de Fatima avant de dormir", "Gloire à Allah (33 fois), louange à Allah (33 fois), Allah est le Plus Grand (34 fois).", "Avant de dormir — enseigné par le Prophète ﷺ à Fatima et Ali.", "Le Prophète ﷺ a dit que cela valait mieux pour eux qu'un serviteur."),
        "dua_sleep_qina_adhab" to DuaText("Protection contre le châtiment", "Ô Allah, préserve-moi de Ton châtiment le jour où Tu ressusciteras Tes serviteurs.", "Main droite sous la joue, à dire trois fois.", "Rappelle la mort et prépare à l'au-delà avant le sommeil."),
        "dua_bad_dream" to DuaText("En cas de mauvais rêve", "Je cherche refuge auprès d'Allah contre le diable maudit.", "En cas de mauvais rêve : souffler légèrement trois fois à gauche puis changer de côté.", "Le mauvais rêve ne pourra pas nuire ; ne le raconter à personne."),
        "dua_yunus" to DuaText("L'invocation du prophète Jonas (Yûnus)", "Nulle divinité que Toi, gloire à Toi ! J'ai été vraiment du nombre des injustes.", "L'invocation du prophète Jonas dans le ventre de la baleine — pour toute épreuve.", "Aucun musulman ne l'a invoquée pour une affaire sans qu'Allah ne lui réponde."),
        "dua_karb" to DuaText("Invocation en cas de grande détresse", "Nulle divinité sauf Allah, l'Immense, le Longanime. Nulle divinité sauf Allah, Seigneur du Trône immense. Nulle divinité sauf Allah, Seigneur des cieux, de la terre et du Trône généreux.", "En cas de grande détresse et d'angoisse.", "Le Prophète ﷺ la disait dans la détresse."),
        "dua_ya_hayyu_ya_qayyum" to DuaText("Ô Vivant, ô Celui qui subsiste par Lui-même", "Ô Vivant, ô Celui qui subsiste par Lui-même, c'est par Ta miséricorde que j'implore le secours.", "Quand une affaire devient très lourde à porter.", "Le Prophète ﷺ la disait quand une affaire le préoccupait."),
        "dua_hasbunallah" to DuaText("Allah nous suffit", "Allah nous suffit, Il est le meilleur garant.", "Face à la peur de l'ennemi ou à un grand danger.", "Dite par Abraham lorsqu'il fut jeté dans le feu, et par le Prophète ﷺ face au danger."),
        "dua_entering_home" to DuaText("En entrant à la maison", "Au nom d'Allah, nous entrons, au nom d'Allah, nous sortons, et sur Allah, notre Seigneur, nous nous reposons.", "À dire en entrant chez soi, avec le salut.", "Celui qui évoque Allah en entrant chez lui et en mangeant, le diable dit : il n'y a ici ni logis ni repas pour vous."),
        "dua_travel" to DuaText("Invocation du voyage", "Gloire à Celui qui nous a soumis cela, nous n'aurions pu le dominer par nous-mêmes ; et c'est vers notre Seigneur que nous retournerons.", "À dire une fois en selle, après avoir dit trois fois Allahu Akbar.", "Invocation prophétique du voyage, pour la protection et la bénédiction."),
        "dua_entering_market" to DuaText("En entrant au marché", "Nulle divinité sauf Allah, Seul, sans associé. À Lui la royauté et la louange. Il donne la vie et la mort, Il est Vivant et ne meurt jamais. Le bien est dans Sa main et Il est capable de toute chose.", "À dire en entrant au marché.", "Un immense mérite est rapporté dans le hadith pour cette invocation."),
        "dua_adam_forgiveness" to DuaText("L'invocation d'Adam", "Seigneur, nous nous sommes fait du tort à nous-mêmes ; si Tu ne nous pardonnes pas et ne nous fais pas miséricorde, nous serons certainement du nombre des perdants.", "L'invocation de repentir d'Adam et Ève.", "Le premier repentir de l'humanité — accepté par Allah."),
        "dua_abu_bakr" to DuaText("Invocation enseignée à Abû Bakr", "Ô Allah, je me suis beaucoup fait du tort à moi-même, et nul ne pardonne les péchés hormis Toi ; accorde-moi un pardon venant de Toi et fais-moi miséricorde, car Tu es le Pardonneur, le Miséricordieux.", "Enseignée par le Prophète ﷺ à Abû Bakr pour la prière.", "Invocation prophétique à dire à la fin de la prière."),
        "dua_astaghfirullah_atubu" to DuaText("Le repentir quotidien", "Je demande pardon à Allah et je me repens à Lui.", "Le Prophète ﷺ demandait pardon plus de soixante-dix fois par jour.", "Le Prophète ﷺ a dit demander pardon à Allah plus de soixante-dix fois par jour."),
        "dua_laylatul_qadr" to DuaText("Invocation de la Nuit du Destin", "Ô Allah, Tu es Celui qui pardonne, Tu aimes le pardon, pardonne-moi donc.", "Enseignée à Aïcha pour la Nuit du Destin.", "Invocation spéciale des dix dernières nuits de Ramadan et de Laylat al-Qadr."),
        "dua_family_coolness" to DuaText("La fraîcheur des yeux (épouse et enfants)", "Seigneur, accorde-nous, en nos épouses et nos descendants, la fraîcheur des yeux, et fais de nous un modèle pour les pieux.", "Invocation coranique pour un conjoint et des enfants vertueux.", "Pour la sérénité du foyer et une descendance pieuse."),
        "dua_righteous_children" to DuaText("Pour une descendance vertueuse", "Seigneur, accorde-moi, venant de Toi, une descendance pure ; Tu es Celui qui exauce l'invocation.", "L'invocation de Zacharie.", "Invocation coranique pour demander une descendance."),
        "dua_ibrahim_prayer_family" to DuaText("Ceux qui accomplissent la prière", "Seigneur, fais que j'accomplisse la prière, ainsi que ma descendance. Seigneur, exauce mon invocation. Seigneur, pardonne-moi, à mes parents et aux croyants, le Jour où se dressera le compte.", "L'invocation d'Abraham pour lui-même et sa descendance.", "Généralement récitée à la fin de la prière."),
        "dua_newlywed" to DuaText("Félicitations aux mariés", "Qu'Allah te bénisse, répande sur toi Sa bénédiction, et vous unisse dans le bien.", "À dire à celui qui se marie.", "Félicitations prophétiques pour le mariage."),
        "dua_before_eating" to DuaText("Avant de manger", "Au nom d'Allah. (En cas d'oubli :) Au nom d'Allah, au début et à la fin.", "Avant de manger ; en cas d'oubli, à dire en cours de repas.", "En disant le Bismillah, le diable ne participe pas au repas."),
        "dua_after_eating" to DuaText("Après avoir mangé", "Louange à Allah qui m'a nourri de ceci et me l'a accordé sans force ni puissance de ma part.", "Après avoir fini de manger.", "Les péchés passés de celui qui la dit sont pardonnés."),
        "dua_host" to DuaText("Pour l'hôte", "Ô Allah, bénis ce que Tu leur as accordé, pardonne-leur et fais-leur miséricorde.", "Après avoir mangé chez quelqu'un, pour l'hôte.", "Remerciement prophétique de l'hôte."),
        "dua_breaking_fast" to DuaText("À la rupture du jeûne", "La soif est partie, les veines se sont abreuvées, et la récompense est acquise, si Allah le veut.", "Au moment de l'iftar.", "Le Prophète ﷺ le disait à la rupture du jeûne."),
        "dua_new_clothes" to DuaText("En portant un vêtement neuf", "Ô Allah, à Toi la louange, c'est Toi qui m'as vêtu ; je Te demande son bien et le bien pour lequel il a été fait, et je cherche refuge contre son mal et le mal pour lequel il a été fait.", "En portant un vêtement neuf, en le nommant.", "Le Prophète ﷺ le disait en portant un habit neuf."),
        "dua_rabbana_atina" to DuaText("Le bien ici-bas et dans l'au-delà", "Seigneur, accorde-nous belle part ici-bas, et belle part aussi dans l'au-delà, et protège-nous du châtiment du Feu.", "L'invocation la plus fréquente du Prophète ﷺ.", "Invocation englobant tout le bien de ce monde et de l'au-delà."),
        "dua_rabbi_zidni_ilma" to DuaText("Accroissement de la science", "Seigneur, accroît ma science.", "Pour demander l'accroissement du savoir.", "Allah a ordonné au Prophète ﷺ de ne demander l'accroissement que du savoir."),
        "dua_musa_sharh_sadr" to DuaText("L'ouverture de la poitrine (Moïse)", "Seigneur, ouvre ma poitrine, facilite ma tâche, et dénoue un nœud de ma langue afin qu'ils comprennent mes paroles.", "Avant un examen, un discours, ou une tâche difficile.", "L'invocation de Moïse — sérénité du cœur et facilité dans la tâche."),
        "dua_la_tuzigh" to DuaText("La fermeté du cœur", "Seigneur, ne laisse pas dévier nos cœurs après nous avoir guidés, et accorde-nous, venant de Toi, une miséricorde ; c'est Toi le Grand Donateur.", "Pour la fermeté du cœur sur la guidée.", "Invocation pour la persévérance dans la foi."),
        "dua_ya_muqallib" to DuaText("Ô Toi qui retournes les cœurs", "Ô Toi qui retournes les cœurs, affermis mon cœur sur Ta religion.", "Le Prophète ﷺ la répétait souvent.", "L'invocation la plus fréquente du Prophète ﷺ selon Umm Salama."),
        "dua_la_tuakhidhna" to DuaText("Les derniers versets de la sourate Al-Baqara", "Seigneur, ne nous châtie pas si nous oublions ou commettons une erreur. Seigneur, ne nous charge pas d'un fardeau comme Tu l'as fait pour ceux qui nous ont précédés. Seigneur, ne nous impose pas ce que nous ne pouvons supporter, efface nos fautes, pardonne-nous et fais-nous miséricorde. Tu es notre Maître, accorde-nous donc la victoire sur les mécréants.", "Avant de dormir — les deux derniers versets de la sourate Al-Baqara.", "Quiconque les récite la nuit, elles lui suffisent."),
        "dua_visiting_sick" to DuaText("Visite au malade", "Je demande à Allah l'Immense, Seigneur du Trône immense, de te guérir.", "Sept fois lors de la visite au malade.", "Si son terme n'est pas arrivé, Allah le guérit."),
        "dua_ruqyah_pain" to DuaText("Pour une douleur du corps", "Je cherche refuge auprès d'Allah et de Sa puissance contre le mal que je ressens et que je crains.", "Poser la main sur la douleur, dire trois fois Bismillah puis sept fois cette invocation.", "Enseignée par le Prophète ﷺ à Uthmân ibn Abî al-'Âs pour la douleur."),
        "dua_ruqyah_nabawi" to DuaText("La ruqya prophétique pour le malade", "Ô Allah, Seigneur des hommes, enlève le mal, guéris, c'est Toi le Guérisseur, il n'y a de guérison que la Tienne, une guérison qui ne laisse aucune maladie.", "En passant la main sur le malade.", "Le Prophète ﷺ la disait en rendant visite aux siens malades."),
        "dua_kalimat_tammat" to DuaText("Refuge par les paroles parfaites d'Allah", "Je cherche refuge dans les paroles parfaites d'Allah contre le mal de ce qu'Il a créé.", "En s'installant quelque part ou le soir.", "Quiconque s'installe quelque part et la dit, rien ne lui nuira jusqu'à son départ."),
        "dua_evil_eye" to DuaText("Protection des enfants (mauvais œil)", "Je vous confie tous deux à la protection des paroles parfaites d'Allah contre tout diable, toute bête venimeuse et tout œil malveillant.", "Le Prophète ﷺ la récitait sur Hassan et Hussein.", "Invocation prophétique pour protéger les enfants du mauvais œil et du mal."),
        "dua_seeing_afflicted" to DuaText("En voyant une personne éprouvée", "Louange à Allah qui m'a préservé de ce dont Il t'a éprouvé, et m'a nettement favorisé par rapport à beaucoup de Ses créatures.", "En voyant une personne éprouvée (à dire intérieurement).", "Celui qui la dit sera préservé de cette épreuve."),
        "dua_istikhara" to DuaText("La prière de consultation (Istikhâra)", "Ô Allah, je Te consulte par Ta science, je Te demande de me donner la capacité par Ta puissance, et je Te demande de Ton immense faveur, car Tu es capable et je ne le suis pas, Tu sais et je ne sais pas, et Tu es le Grand Connaisseur de l'invisible. Ô Allah, si Tu sais que cette affaire est un bien pour moi dans ma religion, ma vie et l'issue de mon sort, alors destine-la moi, facilite-la moi, puis bénis-la moi. Et si Tu sais qu'elle est un mal pour moi dans ma religion, ma vie et l'issue de mon sort, alors éloigne-la de moi et éloigne-moi d'elle, et destine-moi le bien où qu'il soit, puis satisfais-m'en.", "Après deux unités de prière surérogatoire, pour demander le bien dans une affaire licite.", "Le Prophète ﷺ enseignait l'Istikhâra à ses compagnons comme une sourate du Coran."),
        "dua_allahumma_bika_asbahna" to DuaText("Ô Allah, par Toi nous voici au matin", "Ô Allah, par Toi nous voici au matin et par Toi nous voici au soir, par Toi nous vivons et par Toi nous mourrons, et c'est vers Toi que se fera la résurrection.", "Le matin.", "Le Prophète ﷺ l'enseignait matin et soir."),
        "dua_allahumma_bika_amsayna" to DuaText("Ô Allah, par Toi nous voici au soir", "Ô Allah, par Toi nous voici au soir et par Toi nous voici au matin, par Toi nous vivons et par Toi nous mourrons, et c'est vers Toi que sera le retour.", "Le soir.", "Le Prophète ﷺ l'enseignait matin et soir."),
        "dua_afiyah_morning" to DuaText("Invocation pour la santé", "Ô Allah, je Te demande le pardon et la bonne santé ici-bas et dans l'au-delà.", "Le Prophète ﷺ ne la délaissait jamais, matin et soir.", "Rien de meilleur n'a été accordé à quiconque que la bonne santé."),
        "dua_afini_fi_badani" to DuaText("Santé du corps, de l'ouïe et de la vue", "Ô Allah, accorde-moi la santé dans mon corps, accorde-moi la santé dans mon ouïe, accorde-moi la santé dans ma vue ; nulle divinité que Toi.", "Trois fois le matin et le soir.", "Invocation pour préserver la santé et les sens."),
        "dua_ya_hayyu_aslih" to DuaText("Arrange toute mon affaire", "Ô Vivant, ô Celui qui subsiste par Lui-même, c'est par Ta miséricorde que j'implore le secours ; arrange toute mon affaire et ne me laisse pas à moi-même, ne serait-ce qu'un clin d'œil.", "Le Prophète ﷺ a recommandé à Fatima de la dire matin et soir.", "Demander l'aide d'Allah en toute affaire."),
        "dua_subhanallah_adada_khalqihi" to DuaText("Le tasbîh de Juwayriya", "Gloire à Allah et louange à Lui, à hauteur du nombre de Ses créatures, de Son agrément, du poids de Son Trône, et de l'encre de Ses paroles.", "Trois fois le matin — équivaut à des heures d'évocation.", "Ces quatre paroles, dites trois fois, sont plus lourdes que l'évocation du matin jusqu'à midi."),
        "dua_salawat" to DuaText("La prière abrahamique sur le Prophète", "Ô Allah, prie sur Muhammad et sur la famille de Muhammad comme Tu as prié sur Abraham et la famille d'Abraham, Tu es Digne de louange et de gloire. Ô Allah, bénis Muhammad et la famille de Muhammad comme Tu as béni Abraham et la famille d'Abraham, Tu es Digne de louange et de gloire.", "Dans la prière et à tout moment.", "Quiconque prie une fois sur le Prophète ﷺ, Allah prie sur lui dix fois."),
        "dua_wudu_after" to DuaText("Après les ablutions", "J'atteste que nulle divinité que Allah, Seul, sans associé, et j'atteste que Muhammad est Son serviteur et Son messager. Ô Allah, fais de moi l'un de ceux qui se repentent et l'un de ceux qui se purifient.", "Après avoir terminé les ablutions.", "Les huit portes du Paradis lui sont ouvertes, il y entre par celle qu'il souhaite."),
        "dua_wudu_before" to DuaText("Avant les ablutions", "Au nom d'Allah.", "En commençant les ablutions.", "Celui qui n'a pas invoqué le nom d'Allah n'a pas d'ablutions (complètes)."),
        "dua_istiftah" to DuaText("L'invocation d'ouverture de la prière", "Gloire à Toi, ô Allah, et louange à Toi ; béni soit Ton nom, exaltée soit Ta grandeur, il n'y a de divinité que Toi.", "Au début de la prière, juste après le takbîr d'entrée.", "L'invocation d'ouverture prophétique de la prière."),
        "dua_ruku" to DuaText("Dans l'inclinaison (rukû')", "Gloire à mon Seigneur l'Immense.", "Au moins trois fois pendant le rukû'.", "Le tasbîh prophétique du rukû'."),
        "dua_sujood" to DuaText("Dans la prosternation (sujûd)", "Gloire à mon Seigneur le Très-Haut.", "Au moins trois fois pendant le sujûd.", "Le serviteur est au plus près de son Seigneur lorsqu'il est prosterné."),
        "dua_rising_ruku" to DuaText("En se relevant du rukû'", "Allah entend celui qui Le loue. Seigneur, à Toi la louange.", "En se relevant du rukû' et se tenant debout.", "Celui dont la parole coïncide avec celle des anges voit ses péchés passés pardonnés."),
        "dua_between_sajdas" to DuaText("Entre les deux prosternations", "Seigneur, pardonne-moi, Seigneur, pardonne-moi.", "Assis entre les deux prosternations.", "L'invocation prophétique de cette position assise."),
        "dua_before_salam_four" to DuaText("Refuge contre quatre choses avant le salut final", "Ô Allah, je cherche refuge auprès de Toi contre le châtiment de l'Enfer, contre le châtiment de la tombe, contre les épreuves de la vie et de la mort, et contre le mal de l'épreuve du Faux Messie (Dajjâl).", "Après le dernier tashahhud et la prière sur le Prophète, avant le salut final.", "Le Prophète ﷺ a ordonné de chercher refuge contre ces quatre choses."),
        "dua_qunoot_witr" to DuaText("L'invocation du Qunût dans le Witr", "Ô Allah, guide-moi parmi ceux que Tu as guidés, accorde-moi la santé parmi ceux à qui Tu l'as accordée, prends-moi en charge parmi ceux que Tu as pris en charge, bénis ce que Tu m'as donné, et préserve-moi du mal que Tu as décrété. C'est Toi qui décrètes et rien ne peut être décrété contre Toi. Celui que Tu prends pour allié n'est jamais humilié. Béni sois-Tu, notre Seigneur, et élevé au-dessus de tout.", "Dans la prière du Witr — enseignée par le Prophète ﷺ à Al-Hasan ibn 'Alî.", "L'invocation prophétique du Qunût dans le Witr."),
        "dua_qunoot_hanafi" to DuaText("Le Qunût (Allâhumma innâ nasta'înuk)", "Ô Allah, nous Te demandons secours, pardon et guidée, nous croyons en Toi et nous plaçons notre confiance en Toi, nous Te louons de la meilleure façon, nous Te remercions et ne Te renions pas, et nous délaissons quiconque Te désobéit. Ô Allah, c'est Toi seul que nous adorons, c'est pour Toi que nous prions et nous prosternons, c'est vers Toi que nous nous hâtons et nous empressons, nous espérons Ta miséricorde et redoutons Ton châtiment ; en vérité Ton châtiment atteindra les mécréants.", "Dans le Witr — pratique de l'école hanafite.", "Rapporté de 'Umar dans le Qunût."),
        "dua_sleep_aslamtu" to DuaText("Les dernières paroles avant de dormir", "Ô Allah, je me remets entièrement à Toi, je confie mon affaire à Toi, j'adosse mon dos à Toi, par désir et par crainte envers Toi. Il n'y a nul refuge ni nul salut contre Toi si ce n'est auprès de Toi. Je crois en Ton Livre que Tu as révélé et en Ton Prophète que Tu as envoyé.", "Après les ablutions, allongé sur le côté droit — les toutes dernières paroles.", "S'il meurt cette nuit-là, il meurt sur la nature innée (fitra)."),
        "dua_waking_night" to DuaText("En se réveillant la nuit", "Nulle divinité sauf Allah, Seul, sans associé. À Lui la royauté, à Lui la louange, et Il est capable de toute chose. Louange à Allah, gloire à Allah, nulle divinité que Allah, Allah est le plus Grand, il n'y a de force ni de puissance qu'en Allah. Ô Allah, pardonne-moi.", "En se réveillant la nuit.", "Son invocation est exaucée, et s'il fait ses ablutions puis prie, sa prière est acceptée."),
        "dua_hamm_ibn_masud" to DuaText("Invocation contre le souci (Ibn Mas'ûd)", "Ô Allah, je suis Ton serviteur, fils de Ton serviteur, fils de Ta servante, mon front est entre Tes mains, Ton jugement s'accomplit en moi, Ton décret à mon sujet est juste. Je Te demande par tout nom qui T'appartient, dont Tu T'es nommé, ou que Tu as révélé dans Ton Livre, ou que Tu as enseigné à l'une de Tes créatures, ou que Tu as gardé pour Toi dans la science de l'invisible, de faire du Coran le printemps de mon cœur, la lumière de ma poitrine, la dissipation de ma tristesse et la fin de mon souci.", "En cas de souci et de tristesse — Allah les transforme en joie.", "Allah dissipe son souci et sa tristesse et les remplace par la joie."),
        "dua_difficulty_sahl" to DuaText("Quand une affaire est difficile", "Ô Allah, rien n'est facile hormis ce que Tu rends facile, et Tu rends facile, si Tu le veux, ce qui est pénible.", "Quand une affaire semble difficile.", "Pour faciliter les examens et les affaires difficiles."),
        "dua_musibah" to DuaText("En cas d'épreuve (Istirjâ')", "Nous appartenons à Allah et c'est à Lui que nous retournerons. Ô Allah, récompense-moi dans mon épreuve et accorde-moi mieux en échange.", "En cas de perte ou d'épreuve, quelle qu'elle soit.", "Allah accorde certainement un meilleur remplacement — comme il en fut pour Umm Salama."),
        "dua_debt" to DuaText("Pour se libérer d'une dette", "Ô Allah, suffis-moi par Ton licite face à Ton illicite, et rends-moi, par Ta faveur, indépendant de tout autre que Toi.", "Pour le remboursement d'une dette — enseignée par le Prophète ﷺ à 'Alî.", "Même une dette aussi lourde qu'une montagne, Allah la fera rembourser."),
        "dua_anger" to DuaText("En cas de colère", "Je cherche refuge auprès d'Allah contre le diable maudit.", "En cas de colère.", "Le Prophète ﷺ a dit que la colère s'apaiserait en la disant."),
        "dua_waswasa" to DuaText("Contre les doutes insinués dans la foi", "Je crois en Allah et en Ses messagers.", "En cas de doute insinué par le diable dans la foi.", "À dire puis cesser de penser à ce doute."),
        "dua_travel_full" to DuaText("L'invocation complète du voyage", "Ô Allah, nous Te demandons, dans ce voyage, la piété et la crainte révérencielle, et une œuvre qui Te plaise. Ô Allah, facilite-nous ce voyage et raccourcis-en la distance. Ô Allah, Tu es le Compagnon du voyage et le Gardien de la famille restée derrière.", "Au début du voyage, après « Gloire à Celui qui nous a soumis... ».", "L'invocation prophétique complète du voyage."),
        "dua_return_travel" to DuaText("Au retour de voyage", "Nous revenons, repentants, adorateurs, louant notre Seigneur.", "Au retour de voyage.", "Le Prophète ﷺ la disait en revenant de voyage."),
        "dua_farewell_traveller" to DuaText("Pour saluer un voyageur", "Je confie à Allah ta religion, ta responsabilité et l'issue de tes actes.", "En disant au revoir à un voyageur.", "Ce qui est confié à Allah n'est jamais perdu."),
        "dua_entering_town" to DuaText("En arrivant dans un nouveau lieu", "Je cherche refuge dans les paroles parfaites d'Allah contre le mal de ce qu'Il a créé.", "En s'installant dans un lieu ou une nouvelle ville.", "Rien ne lui nuira jusqu'à ce qu'il quitte ce lieu."),
        "dua_boarding_ship" to DuaText("En embarquant sur un bateau", "Au nom d'Allah, qu'elle vogue et qu'elle mouille ! Mon Seigneur est certes Pardonneur et Miséricordieux.", "En embarquant — parole du prophète Noé.", "Verset coranique — l'invocation de l'arche de Noé."),
        "dua_istighfar_hayyul_qayyum" to DuaText("Repentir par le Vivant, Celui qui subsiste par Lui-même", "Je demande pardon à Allah, nulle divinité que Lui, le Vivant, Celui qui subsiste par Lui-même, et je me repens à Lui.", "Pour se repentir.", "Ses péchés sont pardonnés même s'il a fui le champ de bataille."),
        "dua_rabbighfir_warham" to DuaText("Seigneur, pardonne et fais miséricorde", "Seigneur, pardonne et fais miséricorde, Tu es le Meilleur des miséricordieux.", "Invocation coranique — pardon et miséricorde.", "Dernier verset de la sourate Al-Mu'minûn."),
        "dua_majlis_kaffarah" to DuaText("Expiation de l'assemblée", "Gloire à Toi, ô Allah, et louange à Toi ; j'atteste que nulle divinité que Toi, je Te demande pardon et je me repens à Toi.", "En se levant d'une assemblée.", "Expiation de ce qui s'est dit d'inutile pendant l'assemblée."),
        "dua_jami_forgiveness" to DuaText("L'invocation générale de pardon", "Ô Allah, pardonne mon erreur, mon ignorance, mon excès dans mes affaires, et ce que Tu connais mieux que moi.", "Invocation générale que le Prophète ﷺ récitait.", "Invocation englobante que le Prophète ﷺ répétait souvent."),
        "dua_parents_nuh" to DuaText("L'invocation de Noé pour les parents", "Seigneur, pardonne-moi, ainsi qu'à mes parents, à quiconque entre dans ma maison croyant, et à tous les croyants et croyantes.", "Pour les parents et les croyants.", "L'invocation du prophète Noé."),
        "dua_shukr_parents" to DuaText("Gratitude pour les parents et descendance vertueuse", "Seigneur, inspire-moi de rendre grâce pour Ton bienfait dont Tu m'as comblé ainsi que mes parents, et d'accomplir de bonnes œuvres que Tu agrées, et fais que ma descendance soit de bonnes gens. Je me repens à Toi et je suis du nombre des soumis.", "Invocation coranique pour celui qui atteint quarante ans.", "Gratitude, bonnes œuvres et rectitude de la descendance réunies en une seule invocation."),
        "dua_intimacy" to DuaText("Avant l'intimité conjugale", "Au nom d'Allah. Ô Allah, éloigne de nous le diable et éloigne le diable de ce que Tu nous accorderas.", "Avant l'intimité conjugale.", "Si un enfant est destiné à naître, le diable ne pourra jamais lui nuire."),
        "dua_ibrahim_children_protection" to DuaText("Protection du foyer et de la descendance", "Seigneur, fais de cette cité un lieu sûr, et préserve-moi ainsi que mes enfants d'adorer les idoles.", "L'invocation d'Abraham pour la protection de la cité et de la descendance.", "Invocation pour la fermeté sur le monothéisme."),
        "dua_drinking_milk" to DuaText("En buvant du lait", "Ô Allah, bénis-le pour nous et accorde-nous-en davantage.", "En buvant du lait.", "Le lait tient lieu à la fois de nourriture et de boisson."),
        "dua_iftar_host" to DuaText("En rompant le jeûne chez quelqu'un", "Que les jeûneurs rompent le jeûne chez vous, que les gens vertueux mangent votre nourriture, et que les anges prient pour vous.", "En rompant le jeûne chez quelqu'un.", "L'invocation prophétique pour l'hôte."),
        "dua_seeing_first_fruit" to DuaText("En voyant le premier fruit", "Ô Allah, bénis nos fruits, bénis notre cité, bénis notre sâ' et notre mudd (nos mesures).", "En voyant le premier fruit de la saison.", "Invocation pour la bénédiction de la subsistance et de la cité."),
        "dua_good_news" to DuaText("En recevant une bonne nouvelle", "Louange à Allah par la grâce de qui s'accomplissent les bonnes œuvres.", "En recevant une bonne nouvelle (et prosternation de gratitude).", "Le Prophète ﷺ la disait en voyant ce qu'il aimait."),
        "dua_looking_mirror" to DuaText("En se regardant dans un miroir", "Ô Allah, de même que Tu as embelli mon apparence, embellis aussi mon caractère.", "En se regardant dans un miroir.", "Le Prophète ﷺ faisait cette invocation."),
        "dua_rabbana_taqabbal" to DuaText("L'acceptation des œuvres", "Seigneur, accepte de nous cette œuvre ; c'est Toi, en vérité, l'Audient, l'Omniscient. Et accueille notre repentir, c'est Toi, en vérité, l'Accueillant au repentir, le Miséricordieux.", "L'invocation d'Abraham et Ismaël lors de la construction de la Kaaba.", "Invocation pour l'acceptation d'une bonne œuvre après son accomplissement."),
    )
}
